import {TACTICS,DESCRIPTIONS,ATTRS,createMatch,beginTurn,resolve,displayAttacks,statusLabels,activated,rng} from './engine.js';
import {chooseCpu} from './cpu.js';
import {BattleAudio} from './audio.js';
import {BattlePresentation} from './presentation.js';
const app=document.querySelector('#app'),detail=document.querySelector('#detail-dialog'),rules=document.querySelector('#rules-dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,presentation,sound,fx,step=0,charId=160,tactics=[],focus=160,query='',filter='',phase='setup';
let match=null,cpuAction=null,chosenSlot=-1,pendingSlot=-1,random=Math.random,notice='',displayState=null,epoch=0;
const tone=['fire','leaf','water'],icons=['R_fire.png','P_leaf.png','S_water.png'];
const card=id=>data.cards[id];
const cardLabel=c=>c.type?`${c.character} · ${TACTICS[c.type]}`:`${c.character} · ${c.rarity}`;
const image=(c,extra='',back=false)=>`<img ${extra} src="${back&&c.backImage?c.backImage:c.image}" alt="${esc(c.name)}" width="384" height="512">`;
const stats=values=>`<div class="stats">${values.map((n,i)=>`<div class="stat ${tone[i]}"><img src="assets/ui/${icons[i]}" alt=""><span>${ATTRS[i]}</span><strong>${n}</strong></div>`).join('')}</div>`;
const slotImages=()=>[0,1,2].map(i=>tactics[i]!==undefined?`<button class="deck-slot filled" data-remove="${i}" aria-label="${esc(cardLabel(card(tactics[i])))}を外す">${image(card(tactics[i]))}<span class="slot-x">×</span></button>`:`<div class="deck-slot" aria-label="戦術${i+1} 未選択">${i+1}</div>`).join('');
document.querySelector('#rules-open').addEventListener('click',()=>rules.showModal());
for(const modal of [detail,rules])modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('[data-close]'))modal.close();});
document.querySelector('#audio-toggle').addEventListener('click',()=>{if(!sound)return;sound.setEnabled(!sound.enabled);updateAudio();});
document.querySelector('#volume').addEventListener('input',e=>{if(!sound)return;sound.unlock();sound.setVolume(Number(e.target.value)/100);});
function updateAudio(){const b=document.querySelector('#audio-toggle');b.textContent=sound.enabled?'音 ON':'音 OFF';b.setAttribute('aria-pressed',String(sound.enabled));}
function showDetail(id,back=false){const c=card(id);detail.innerHTML=`<div class="dialog-head"><h2>${esc(cardLabel(c))}</h2><button class="quiet" data-close>閉じる</button></div><div class="detail-layout">${image(c,'',back)}<div><div class="card-code">${esc(c.name)}</div>${c.type?`<p>${esc(DESCRIPTIONS[c.type])}</p>`:stats(c.atk.map(v=>v+(back?50:0)))}${c.ssr?'<p class="muted">5ターン目に変身し、全属性の攻撃力が50上がります。</p>':''}${c.growth?'<p class="muted">毎ターン、ランダムな属性の基礎攻撃力＋50。勝った属性はさらに＋50。</p>':''}</div></div>`;detail.showModal();}
function renderSetup(){phase='setup';app.className='setup-app';app.innerHTML=`<section class="deck-screen"><header class="deck-header"><h1>${step===0?'キャラクター選択':'戦術選択'}</h1><div class="selected-row"><span>選出</span><div class="deck-slots">${slotImages()}</div></div><nav class="steps" aria-label="デッキ選択"><button data-step="0" class="${step===0?'active':''}">1 キャラ</button><button data-step="1" class="${step===1?'active':''}">2 戦術</button></nav></header><div class="setup-layout"><aside class="selection-panel" id="selection"></aside><section class="catalog" aria-label="カード一覧"><div class="catalog-top"><span id="catalog-count"></span><span>カードを選択 →「選ぶ」</span></div><div class="card-scroll" tabindex="0" aria-label="カード一覧をスクロール"><div class="card-grid" id="card-grid"></div></div></section></div><footer class="deck-footer"><button class="back-button" data-action="${step===0?'clear':'characters'}">戻る</button><div class="filters"><input id="search" type="search" aria-label="カードを検索" placeholder="キャラ名・カード名" value="${esc(query)}"><select id="filter" aria-label="${step===0?'レアリティ':'戦術の効果'}で絞り込み"><option value="">絞り込み</option>${(step===0?['R','SR','USR','SUSR','SSR'].map(v=>[v,v]):TACTICS.slice(1).map((v,i)=>[String(i+1),v])).map(([v,label])=>`<option value="${v}" ${filter===v?'selected':''}>${esc(label)}</option>`).join('')}</select></div><button class="primary" data-action="${step===0?'tactics':'start'}" ${step===1&&tactics.length!==3?'disabled':''}>${step===0?'戦術を選ぶ':'CPUと対戦する'}</button></footer></section>`;renderSelection();renderCatalog();}
function renderSelection(){const c=card(focus),selected=step===0?c.id===charId:tactics.includes(c.id);document.querySelector('#selection').innerHTML=`${image(c,'class="focus-image" tabindex="0" role="button" aria-label="カードを拡大" data-detail="'+c.id+'"')}<div class="focus-info"><div class="focus-title">${esc(cardLabel(c))}</div><div class="card-code">${esc(c.name)}</div>${c.type?`<p class="focus-description">${esc(DESCRIPTIONS[c.type])}</p>`:stats(c.atk)}${c.growth?'<p class="muted">ターン終了ごとに攻撃力が成長</p>':''}${c.ssr?'<p class="muted">5ターン目に変身・全属性＋50</p>':''}</div><div class="notice" role="status">${esc(notice)}</div><button class="primary choose-card" data-action="select-focus">${selected?'選択済み':'選ぶ'}</button>`;}
function filtered(){const q=query.trim().toLowerCase();return data.cards.filter(c=>(step===0?c.type===0:c.type>0)&&(!filter||(step===0?c.rarity===filter:c.type===Number(filter)))&&(!q||`${c.name} ${c.character} ${TACTICS[c.type]}`.toLowerCase().includes(q)));}
function renderCatalog(){const list=filtered();document.querySelector('#catalog-count').textContent=`${list.length}枚 · ${step===0?'キャラ1枚':`戦術 ${tactics.length} / 3枚`}`;document.querySelector('#card-grid').innerHTML=list.length?list.map(c=>{const selected=step===0?c.id===charId:tactics.includes(c.id);return `<button class="catalog-card ${selected?'selected':''} ${c.id===focus?'focused':''}" data-select="${c.id}" aria-label="${esc(cardLabel(c))} ${esc(c.name)}" aria-pressed="${selected}">${image(c,'loading="lazy" decoding="async"')}${selected?'<span class="selection-check">✓</span>':''}<span class="name">${esc(c.character)} ${c.type?TACTICS[c.type]:c.rarity}</span></button>`;}).join(''):'<p class="empty">該当するカードがありません。</p>';}
function stopBattle(){epoch++;fx.cancel();sound.stop();displayState=null;}
function changeStep(n){if(phase!=='setup')stopBattle();step=n;query='';filter='';notice='';focus=n===0?charId:tactics[0]??0;renderSetup();}
function selectFocus(){notice='';if(step===0){charId=focus;}else if(tactics.includes(focus)){tactics=tactics.filter(v=>v!==focus);}else if(tactics.length<3){tactics.push(focus);}else notice='3枚選択済みです。上の選出カードを押すと外せます。';const scroll=document.querySelector('.card-scroll')?.scrollTop||0;renderSetup();document.querySelector('.card-scroll').scrollTop=scroll;}
async function start(){if(tactics.length!==3)return;stopBattle();const seed=crypto.getRandomValues(new Uint32Array(1))[0];random=rng(seed);const chars=data.cards.filter(c=>c.type===0),all=data.cards.filter(c=>c.type>0),cpuChar=chars[Math.floor(random()*chars.length)].id,cpuDeck=[];while(cpuDeck.length<3){const id=all[Math.floor(random()*all.length)].id;if(!cpuDeck.includes(id))cpuDeck.push(id);}match=createMatch(data,[charId,cpuChar],[[...tactics],cpuDeck]);sound.startMusic();window.scrollTo({top:0,behavior:'instant'});await nextTurn(true);}
async function nextTurn(first=false){const serial=++epoch;fx.cancel();const before=structuredClone(match);beginTurn(match,data);cpuAction=chooseCpu(match,data,random);chosenSlot=-1;pendingSlot=-1;const transformed=match.sides.map((s,i)=>s.transformed&&!before.sides[i].transformed?i:-1).filter(i=>i>=0);displayState=transformed.length?before:null;phase=first?'intro':transformed.length?'transform':'tactic';renderBattle();if(first)await fx.intro();if(transformed.length)await fx.transform(transformed,data,match,i=>{displayState.sides[i].transformed=true;document.querySelector(`[data-fighter="${i}"] .stats`).outerHTML=stats(displayAttacks(match.sides[i],data));});if(serial!==epoch)return;displayState=null;phase='tactic';renderBattle();}
function fighter(i){const s=(displayState||match).sides[i],c=card(s.card),pct=Math.max(0,Math.min(100,s.hp/data.settings.baseHP*100)),hpColor=presentation.hpColors[pct>50?0:pct>20?1:2];return `<section class="fighter ${s.transformed?'transformed':''}" data-fighter="${i}"><div class="fighter-body"><div class="attack-stats">${stats(displayAttacks(s,data))}</div><div class="card-stage">${image(c,'class="battle-card" tabindex="0" role="button" aria-label="キャラカードを拡大" data-detail="'+c.id+'" data-back="'+s.transformed+'"',s.transformed)}<div class="card-fx fx-layer" aria-hidden="true"></div></div><div class="played-tactic" aria-live="polite"></div></div><div class="hp-track" role="meter" aria-label="${i===0?'あなた':'CPU'}のHP" aria-valuenow="${s.hp}" aria-valuemin="0" aria-valuemax="1000"><div class="hp-fill" style="width:${pct}%;background:${hpColor}"></div><div class="hp-number"><span class="hp-current">${s.hp}</span><small> / 1000</small></div></div><div class="fighter-heading"><strong>${i===0?'あなた':'CPU'}</strong><span>${esc(c.character)} · ${c.rarity}</span></div><div class="status-list">${statusLabels(s).map(v=>`<span class="status-tag ${/毒|睡眠|予告/.test(v)?'bad':''}">${statusIcon(v)}${esc(v)}</span>`).join('')||'<span class="muted">状態異常なし</span>'}</div></section>`;}
function statusIcon(value){const kind=value.includes('毒')?'poison':value.includes('復讐')?'revenge':value.includes('睡眠')?'sleep':value.includes('狂化')?'berserk':value.includes('予告')?'foretell':null;return kind?`<img src="assets/ui/status_icon_${kind}.png" alt="">`:'';}
const phaseName=()=>({intro:'対戦開始',transform:'SSR変身',tactic:'戦術選択',attribute:'属性選択',animating:'SHOWDOWN',result:match.winner<0?'結果発表':'ゲーム終了！'}[phase]);
function renderBattle(){const history=phase==='animating'?match.history.slice(0,-1):match.history;app.className='battle-app';app.innerHTML=`<div class="battle-top"><span>MinettePia CARD BATTLE</span><button class="quiet" data-action="exit">デッキ選択へ戻る</button></div><section class="monitor"><h1 class="phase-name">${phaseName()}</h1><div class="arena">${fighter(0)}<div class="versus"><span>ターン</span><strong>${match.turn}</strong><div class="move-reveal">VS</div></div>${fighter(1)}</div><div id="screen-fx" class="fx-layer" aria-hidden="true"></div></section><section class="tablet"><div class="tablet-heading"><span>あなたの手元</span><span class="opponent-hint"></span></div><div id="actions" class="action-panel"></div></section><details class="history"><summary>対戦ログ · ${history.length}ターン</summary><ol>${history.map(h=>`<li>${h.turn}ターン：${ATTRS[h.moves[0]]} vs ${ATTRS[h.moves[1]]} ／ あなた −${h.damage[0]}、CPU −${h.damage[1]}<br>${h.used.map((id,i)=>`${i===0?'あなた':'CPU'}：${id<0?'戦術なし':TACTICS[card(id).type]}`).join(' ／ ')}</li>`).join('')||'<li>まだ結果はありません。</li>'}</ol></details><div class="live" role="status" aria-live="polite"></div>`;renderActions();if(phase==='result')renderRevealed();}
function renderRevealed(){const r=match.history.at(-1);document.querySelector('.move-reveal').innerHTML=r.moves.map((m,i)=>`<span class="${tone[m]}">${i===0?'あなた':'CPU'}<b>${ATTRS[m]}</b></span>`).join('');for(let i=0;i<2;i++){const box=document.querySelector(`[data-fighter="${i}"] .played-tactic`);if(phase==='result')box.innerHTML=r.used[i]<0?'<span>戦術なし</span>':`${image(card(r.used[i]))}<span>${activated(r,i)?'発動':'不発'}</span>`;if(phase==='result')box.classList.toggle('tactic-failed',r.used[i]>=0&&!activated(r,i));}}
function renderActions(){const area=document.querySelector('#actions'),hint=document.querySelector('.opponent-hint');hint.textContent=phase==='attribute'&&cpuAction.slot>=0?'相手が戦術を使ってきそうだ':'';if(phase==='tactic'){const chosen=pendingSlot>=0?card(match.sides[0].deck[pendingSlot].id):null;area.innerHTML=`<h2>戦術を選ぶ</h2><div class="tactic-select"><div class="tactic-hand">${match.sides[0].deck.map((d,i)=>{const c=card(d.id);return `<button class="tactic-choice ${pendingSlot===i?'selected':''} ${d.left?'':'used'}" data-slot="${i}" ${d.left?'':'disabled'} aria-pressed="${pendingSlot===i}" aria-label="${TACTICS[c.type]} ${d.left?'を選択':'使用済み'}">${image(c)}<b>${TACTICS[c.type]}</b><span>${d.left?'':'使用済み'}</span></button>`;}).join('')}</div><div class="tactic-description"><p class="tactic-prompt">${chosen?'選択した戦術':'使う戦術カードをタップして選択'}</p><h3>${chosen?TACTICS[chosen.type]:'このターンは戦術を使わない'}</h3><p class="full-description">${chosen?esc(DESCRIPTIONS[chosen.type]):'戦術カードは1枚につき1回使えます。'}</p><div class="confirmation"><button class="primary" data-action="confirm-tactic">${chosen?'この戦術を使う':'戦術なし'}</button>${chosen?'<button class="quiet" data-action="cancel-tactic">取り消し</button>':''}</div></div></div>`;}else if(phase==='attribute'){const a=displayAttacks(match.sides[0],data);area.innerHTML=`<div class="action-head"><h2>属性を選ぶ</h2><button class="quiet" data-action="back-tactic">戦術を選び直す</button></div><div class="chosen-note">${chosenSlot<0?'戦術なし':`選択した戦術：${TACTICS[card(match.sides[0].deck[chosenSlot].id).type]}`}</div><div class="attribute-choices">${ATTRS.map((name,i)=>`<button class="attribute-choice ${tone[i]}" data-move="${i}" aria-label="${name} 攻撃力${a[i]} を選ぶ"><img src="assets/ui/${icons[i]}" alt=""><span>${name}</span><strong>${a[i]}</strong></button>`).join('')}</div><p class="attribute-rule">火は草に、草は水に、水は火に勝ちます</p>`;}else if(phase==='result'){const r=match.history.at(-1),finished=match.winner!==-1;const title=finished?(match.winner===0?'引き分け':match.winner===1?'勝利!!':'敗北…'):(r.roundWinner===0?'DRAW':r.roundWinner===1?'WIN!':'LOSE...');area.innerHTML=`<div class="result-heading"><h2 class="result-title ${r.roundWinner===1?'win':''}">${title}</h2>${!finished?'<button class="primary" data-action="next-turn">次のターンへ</button>':''}</div><div class="result-details">${[0,1].map(i=>`<div class="result-side"><strong>${i===0?'あなた':'CPU'} <span class="damage">−${r.damage[i]} HP</span></strong><p>${r.used[i]<0?'戦術なし':`${TACTICS[card(r.used[i]).type]} · ${activated(r,i)?'発動':'不発'}`}</p>${r.used[i]>=0?`<p class="full-description">${esc(DESCRIPTIONS[card(r.used[i]).type])}</p>`:''}${r.copied[i]>=0?`<p>体得 → ${TACTICS[card(r.copied[i]).type]}（再使用可）</p>`:''}</div>`).join('')}</div>${finished?'<div class="finish-actions"><button class="primary" data-action="rematch">同じデッキでもう一度</button><button class="quiet" data-action="deck">デッキを組み直す</button></div>':'<p class="next-countdown" role="status"></p>'}`;}else{area.innerHTML=`<div class="waiting"><h2>${phase==='intro'?'対戦開始':phase==='transform'?'SSR変身中':'結果を表示中'}</h2><p>${phase==='transform'?'すべての属性の攻撃力＋50':phase==='intro'?'キャラ1枚・戦術3枚で対戦':'選択した属性と戦術を公開します'}</p><div class="waiting-dots" aria-hidden="true">● ● ●</div></div>`;}}
function chooseTactic(slot){if(phase!=='tactic'||!Number.isInteger(slot)||slot< -1||slot>2||(slot>=0&&!match.sides[0].deck[slot].left))throw Error('その戦術は選べません。');pendingSlot=slot;renderActions();}
function confirmTactic(){if(phase!=='tactic')return;chosenSlot=pendingSlot;phase='attribute';renderBattle();for(let i=0;i<2;i++)if((i===0?chosenSlot:cpuAction.slot)>=0)document.querySelector(`[data-fighter="${i}"] .played-tactic`).innerHTML='<div class="card-back">?</div><span>戦術セット！</span>';}
async function chooseMove(move){if(phase!=='attribute')return;const serial=++epoch;fx.cancel();const roundStart=performance.now();displayState=structuredClone(match);const r=resolve(match,data,[move,cpuAction.move],[chosenSlot,cpuAction.slot],random);phase='animating';renderBattle();await fx.round(r,data,()=>renderRevealed());if(serial!==epoch)return;displayState=null;phase='result';renderBattle();document.querySelector('.live').textContent=`${r.roundWinner===0?'引き分け':r.roundWinner===1?'あなたの属性勝利':'CPUの属性勝利'}。あなたのHP ${match.sides[0].hp}、CPUのHP ${match.sides[1].hp}`;if(match.winner!==-1){fx.finish(match.winner);return;}while(serial===epoch&&phase==='result'){const remaining=Math.max(0,Math.ceil((roundStart+presentation.resultSeconds*1000-performance.now())/1000));const line=document.querySelector('.next-countdown');if(line)line.textContent=remaining?`次のターンまで ${remaining} 秒`:'次のターンへ進みます';if(remaining<=0&&!document.hidden&&!detail.open&&!rules.open){nextTurn();return;}if(!await fx.wait(250))return;}}
function confirmExit(){if(match?.winner===-1){detail.innerHTML='<div class="dialog-head"><h2>対戦を終了しますか？</h2><button class="quiet" data-close>続ける</button></div><p>進行中の対戦はリセットされます。</p><button class="primary" id="confirm-exit">デッキ選択へ戻る</button>';detail.showModal();document.querySelector('#confirm-exit').onclick=()=>{detail.close();changeStep(0);};}else changeStep(0);}
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderCatalog();}});
app.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;renderCatalog();}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();showDetail(Number(e.target.dataset.detail),e.target.dataset.back==='true');}});
app.addEventListener('click',e=>{const el=e.target.closest('button,[data-detail]');if(!el||el.disabled)return;const d=el.dataset;if(d.detail!==undefined)return showDetail(Number(d.detail),d.back==='true');if(d.step!==undefined)return changeStep(Number(d.step));if(d.select!==undefined){focus=Number(d.select);notice='';renderSelection();document.querySelectorAll('[data-select]').forEach(b=>b.classList.toggle('focused',Number(b.dataset.select)===focus));return;}if(d.remove!==undefined){tactics.splice(Number(d.remove),1);renderSetup();return;}if(d.slot!==undefined)return chooseTactic(Number(d.slot));if(d.move!==undefined)return chooseMove(Number(d.move));switch(d.action){case'select-focus':selectFocus();break;case'tactics':changeStep(1);break;case'characters':changeStep(0);break;case'clear':query='';filter='';renderSetup();break;case'start':case'rematch':start();break;case'confirm-tactic':confirmTactic();break;case'cancel-tactic':chooseTactic(-1);break;case'back-tactic':phase='tactic';renderBattle();break;case'next-turn':if(phase==='result')nextTurn();break;case'deck':changeStep(0);break;case'exit':confirmExit();break;}});
function visibleState(){return {phase,turn:match?.turn??0,selectedCharacter:charId,selectedTactics:[...tactics],sides:(displayState||match)?.sides.map((s,i)=>({character:s.card,hp:s.hp,attacks:displayAttacks(s,data),statuses:statusLabels(s),...(i===0?{tactics:s.deck.map(d=>({id:d.id,remaining:d.left}))}:{})}))??[]};}
function webmcp(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'get_visible_battle_state',description:'Read only the visible battle state, excluding hidden CPU tactics and choices.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>visibleState()},{name:'choose_player_tactic',description:'Select and confirm an available tactic slot 0 to 2, or -1 to skip. Advances to attribute selection.',inputSchema:{type:'object',properties:{slot:{type:'integer',minimum:-1,maximum:2}},required:['slot'],additionalProperties:false},execute:({slot})=>{chooseTactic(slot);confirmTactic();return visibleState();}},{name:'choose_player_attribute',description:'Commit fire 0, leaf 1 or water 2, then play the result presentation.',inputSchema:{type:'object',properties:{move:{type:'integer',minimum:0,maximum:2}},required:['move'],additionalProperties:false},execute:({move})=>{if(phase!=='attribute'||!Number.isInteger(move)||move<0||move>2)throw Error('invalid action');chooseMove(move);return visibleState();}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
try{[data,presentation]=await Promise.all(['cards.json','presentation.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('読み込みに失敗しました');return r.json();}));if(data.cards.some((c,i)=>c.id!==i))throw Error('カードデータが不正です');sound=new BattleAudio(presentation);fx=new BattlePresentation(presentation,sound);charId=data.cards.find(c=>c.type===0).id;focus=charId;renderSetup();updateAudio();webmcp();}catch(error){app.innerHTML=`<div class="empty"><h1>カードを読み込めませんでした</h1><p>${esc(error.message)}</p><button onclick="location.reload()">再読み込み</button></div>`;}
